def fakeq_channel(w):
    # symetrique, un scale par canal de sortie (dim 0 des poids conv/linear)
    scale = w.reshape(w.shape[0], -1).abs().amax(dim=1).clamp(min=1e-12) / 127.0
    scale = scale.view([-1] + [1] * (w.dim() - 1))
    return scale * torch.clamp(torch.round(w / scale), QMIN, QMAX)


def relerr(a, b):
    return ((a - b).norm() / a.norm().clamp(min=1e-12)).item()


def quantize_weights(ref, wmode="channel"):
    # deepcopy + substitution des poids par leur fake-quant
    m = copy.deepcopy(ref)
    with torch.no_grad():
        for mod in m.modules():
            if isinstance(mod, (nn.Conv2d, nn.Linear)):
                w = mod.weight.detach()
                mod.weight.copy_(fakeq_channel(w) if wmode == "channel" else fakeq_tensor(w))
    return m


w = model.net[0].weight.detach()
print(f"[erreur relative des poids de la 1ere couche, shape {tuple(w.shape)}]")
print(f"  per-tensor  : {relerr(w, fakeq_tensor(w)):.3e}")
print(f"  per-channel : {relerr(w, fakeq_channel(w)):.3e}  ({w.shape[0]} scales au lieu d'une)")

def weight_modules(m):
    """Les couches porteuses de poids : conv et fc. Les BatchNorm sont hors du compte."""
    return [(name, mod) for name, mod in m.named_modules()
            if isinstance(mod, (nn.Conv2d, nn.Linear))]


def sparsity(m):
    nz = tot = 0
    for _, mod in weight_modules(m):
        tot += mod.weight.numel()
        nz += int((mod.weight != 0).sum())
    return 1.0 - nz / tot


def nonzero_params(m):
    return sum(int((mod.weight != 0).sum()) for _, mod in weight_modules(m))


def zero_tiny_(m):
    """Remet a zero exactement les poids deja nuls par un masque (bruit flottant)."""
    with torch.no_grad():
        for _, mod in weight_modules(m):
            mod.weight.data[mod.weight.data.abs() < 1e-12] = 0.0
    return m


print("modules pondères :", len(weight_modules(model)), "  sparsity initiale :", f"{sparsity(model):.1%}")

def threshold_keep(w, keep_frac):
    """Masque binaire : garde les |w| >= seuil du k-ieme plus grand."""
    flat = w.detach().abs().flatten()
    k = max(1, int(round(keep_frac * flat.numel())))
    if k >= flat.numel():
        return torch.ones_like(w)
    thr = torch.kthvalue(flat, flat.numel() - k + 1).values
    return (w.detach().abs() >= thr).to(w.dtype)


def prune_unstructured_(m, keep_frac, mode="layer"):
    """Applique un masque de magnitude, par couche ou global. Modifie m en place."""
    mods = weight_modules(m)
    if mode == "layer":
        masks = {name: threshold_keep(mod.weight.data, keep_frac) for name, mod in mods}
    elif mode == "global":
        allw = torch.cat([mod.weight.data.detach().abs().flatten() for _, mod in mods])
        k = max(1, int(round(keep_frac * allw.numel())))
        thr = torch.kthvalue(allw, allw.numel() - k + 1).values
        masks = {name: (mod.weight.data.detach().abs() >= thr).to(mod.weight.dtype)
                 for name, mod in mods}
    else:
        raise ValueError(mode)
    with torch.no_grad():
        for name, mod in mods:
            mod.weight.data.mul_(masks[name])
    return masks

def cout_modele(k, b):
    """Longueur de la description du modèle quantifié : k, puis k-1 probabilités à b bits."""
    return 8 + (k - 1) * b


def cout_donnees(compte, b):
    """Longueur d'encodage des données sous le modèle quantifié à b bits."""
    n = sum(compte.values())
    p = {s: c / n for s, c in compte.items()}
    q = {s: max(2 ** -b, round(v * 2 ** b) / 2 ** b) for s, v in p.items()}
    total = sum(q.values())
    q = {s: v / total for s, v in q.items()}
    return -sum(c * math.log2(q[s]) for s, c in compte.items())


LIGNES = []
for b in range(1, 21):
    lh = cout_modele(len(compte), b)
    ld = cout_donnees(compte, b)
    LIGNES.append((b, lh, ld, lh + ld))

print(f"{'b (bits)':>8} {'L(H)':>9} {'L(D|H)':>10} {'total':>10}")
for b, lh, ld, tot in LIGNES:
    marque = "  <- minimum" if tot == min(x[3] for x in LIGNES) else ""
    print(f"{b:>8} {lh:>9.1f} {ld:>10.1f} {tot:>10.1f}{marque}")

b_opt, _, _, l_min = min(LIGNES, key=lambda x: x[3])
print(f"\nPrecision optimale au sens MDL : b* = {b_opt} bits, total {l_min:.1f} bits "
      f"= {l_min / 8:.1f} octets pour {len(TRANCHE)} octets de donnees")

Les trois résultats centraux, lus comme des contrats :

- `kraft_le_one` : la somme de Kraft de **tout** arbre de code est ≤ 1 — aucune implosion possible ;
- `decode_encode` : décoder la concaténation de mots de feuilles redonne **exactement** la liste émise — le contrat d'une table de décodage ;
- `mcmillan_converse` : si une bande de longueurs vérifie Kraft (masse ≤ 2^L), alors un code préfixe avec **exactement ces longueurs** existe — la réciproque, constructive.

## 1. Codes préfixes et somme de Kraft

Pour un arbre de code binaire `t`, `leafWords t` est la liste des mots des feuilles et `kraftSum t` la somme Σ 2^(-|w|). Le lake fournit l'arbre d'exemple `sf4` — le code à 4 symboles de longueurs (1, 2, 3, 3) que le **carnet 02** construit comme « code jouet » (`{a: 8, b: 4, c: 2, d: 2}`, soit la distribution 1/2, 1/4, 1/8, 1/8). Le carnet 01, lui, ne code que la **famille** de longueurs (1, 2, 3, 3) parmi ses exemples de Kraft, et sa seule table de Shannon-Fano est à 6 symboles (longueurs 1, 2, 3, 4, 5, 5).
